-- Local-only additive daily brief preferences, claims and personal reminders.
CREATE TABLE public.brief_preferences(id TEXT PRIMARY KEY,owner TEXT NOT NULL UNIQUE,automatic INTEGER NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE public.brief_deliveries(id TEXT PRIMARY KEY,owner TEXT NOT NULL,local_date TEXT NOT NULL,claimed_at TEXT NOT NULL,UNIQUE(owner,local_date));
CREATE TABLE public.personal_reminders(id TEXT PRIMARY KEY,owner TEXT NOT NULL,title TEXT NOT NULL,due_at TEXT NOT NULL,status TEXT NOT NULL,revision INTEGER NOT NULL,operation_id TEXT NOT NULL,creation_fingerprint TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(owner,operation_id),CHECK(status IN ('active','completed','cancelled')));
CREATE INDEX reminder_owner_due ON personal_reminders(owner,status,due_at);
CREATE TABLE public.reminder_events(id TEXT PRIMARY KEY,reminder_id TEXT NOT NULL REFERENCES public.personal_reminders(id),owner TEXT NOT NULL,revision INTEGER NOT NULL,due_at TEXT NOT NULL,created_at TEXT NOT NULL,read_at TEXT,UNIQUE(reminder_id,revision));
CREATE INDEX reminder_event_owner ON reminder_events(owner,created_at);
ALTER TABLE public.brief_preferences ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.brief_preferences FROM PUBLIC,anon,authenticated,unilus_backend;
GRANT SELECT,INSERT,UPDATE ON public.brief_preferences TO unilus_backend;
CREATE POLICY morning_select ON public.brief_preferences FOR SELECT TO unilus_backend USING(true);
CREATE POLICY morning_insert ON public.brief_preferences FOR INSERT TO unilus_backend WITH CHECK(true);
CREATE POLICY morning_update ON public.brief_preferences FOR UPDATE TO unilus_backend USING(true) WITH CHECK(true);
ALTER TABLE public.brief_deliveries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.brief_deliveries FROM PUBLIC,anon,authenticated,unilus_backend;
GRANT SELECT,INSERT ON public.brief_deliveries TO unilus_backend;
CREATE POLICY morning_select ON public.brief_deliveries FOR SELECT TO unilus_backend USING(true);
CREATE POLICY morning_insert ON public.brief_deliveries FOR INSERT TO unilus_backend WITH CHECK(true);
