GRANT SELECT,INSERT,UPDATE ON public.personal_reminders TO unilus_backend;
CREATE POLICY morning_select ON public.personal_reminders FOR SELECT TO unilus_backend USING(true);
CREATE POLICY morning_insert ON public.personal_reminders FOR INSERT TO unilus_backend WITH CHECK(true);
CREATE POLICY morning_update ON public.personal_reminders FOR UPDATE TO unilus_backend USING(true) WITH CHECK(true);
ALTER TABLE public.reminder_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.reminder_events FROM PUBLIC,anon,authenticated,unilus_backend;
GRANT SELECT,INSERT,UPDATE ON public.reminder_events TO unilus_backend;
CREATE POLICY morning_select ON public.reminder_events FOR SELECT TO unilus_backend USING(true);
CREATE POLICY morning_insert ON public.reminder_events FOR INSERT TO unilus_backend WITH CHECK(true);
CREATE POLICY morning_update ON public.reminder_events FOR UPDATE TO unilus_backend USING(true) WITH CHECK(true);
